#pragma once
#include <cstdint>
namespace kstation {
// Initialise the eight voice records from live K pitch-offset table values.
class VoiceInitTask final {
public:
 enum class Stage{ClearIndex,SetCount,SetBase,SetNote,SetCentre,ClearAge,WriteNote,WriteKey,WriteVelocity,WriteAge,WriteFlags,ReadOffset,WriteOffset,SelectUpper,SetUpperNegative,SkipUpperNegative,SetUpperPositive,CompareUpper,ChooseUpper,SetUpperHigh,SubtractUpper,WriteUpper,TestLower,SelectLower,SetLowerPositive,SkipLowerPositive,SetLowerNegative,CompareLower,ChooseLower,SetLowerLow,SubtractLower,WriteLower,IncrementIndex,MaskIndex,AdvanceVoice,DecrementCount,Repeat,Return,Complete};using S=Stage;enum class Read{Offset};enum class Write{Note,Key,Velocity,Age,Flags,Offset,Upper,Lower};struct Credits{unsigned read=0,write=0,ret=0;};
 S stage()const{return stage_;}bool complete()const{return stage_==S::Complete;}uint8_t index()const{return index_;}uint32_t voice()const{return 0xd030u+18u*index_;}uint32_t offsetAddress()const{return 0xc04cu+index_;}
 unsigned nextClocks(const Credits&c)const{switch(stage_){case S::SetBase:case S::AdvanceVoice:return 9;case S::Repeat:return 8;case S::ReadOffset:return 12+c.read;case S::WriteNote:case S::WriteKey:case S::WriteVelocity:case S::WriteFlags:case S::WriteOffset:case S::WriteUpper:case S::WriteLower:return 12+c.write;case S::WriteAge:return 15+c.write;case S::Return:return c.ret;case S::Complete:return 0;default:return 3;}}
 template<class Reader,class Writer>unsigned advanceBefore(unsigned available,const Credits&c,Reader&&read,Writer&&write){auto cost=nextClocks(c);if(!cost||cost>available)return 0;switch(stage_){case S::WriteNote:write(Write::Note,0x3c);next();break;case S::WriteKey:write(Write::Key,0x3c);next();break;case S::WriteVelocity:write(Write::Velocity,0x40);next();break;case S::WriteAge:write(Write::Age,0);next();break;case S::WriteFlags:write(Write::Flags,0);next();break;case S::ReadOffset:offset_=uint8_t(read(Read::Offset));next();break;case S::WriteOffset:write(Write::Offset,offset_);next();break;case S::SelectUpper:stage_=int8_t(offset_)<0?S::SetUpperNegative:S::SetUpperPositive;break;case S::SetUpperNegative:upper_=0x0f;next();break;case S::SkipUpperNegative:stage_=S::SubtractUpper;break;case S::SetUpperPositive:upper_=0x27;next();break;case S::ChooseUpper:stage_=offset_<=7?S::SubtractUpper:S::SetUpperHigh;break;case S::SetUpperHigh:upper_=0x37;next();break;case S::SubtractUpper:upper_=uint8_t(upper_-offset_);next();break;case S::WriteUpper:write(Write::Upper,upper_);next();break;case S::SelectLower:stage_=int8_t(offset_)<0?S::SetLowerNegative:S::SetLowerPositive;break;case S::SetLowerPositive:lower_=0xef;next();break;case S::SkipLowerPositive:stage_=S::SubtractLower;break;case S::SetLowerNegative:lower_=0xd7;next();break;case S::ChooseLower:stage_=int8_t(offset_)>=-8?S::SubtractLower:S::SetLowerLow;break;case S::SetLowerLow:lower_=0xc7;next();break;case S::SubtractLower:lower_=uint8_t(lower_-offset_);next();break;case S::WriteLower:write(Write::Lower,lower_);next();break;case S::IncrementIndex:++index_;next();break;case S::Repeat:stage_=index_==8?S::Return:S::WriteNote;break;case S::Return:stage_=S::Complete;break;case S::Complete:break;default:next();break;}return cost;}
private:void next(){stage_=S(unsigned(stage_)+1);}S stage_=S::ClearIndex;uint8_t index_=0,offset_=0,upper_=0,lower_=0;
};
}
